#include <bits/stdc++.h>
using namespace std;

const int N = 100, D = 31, MOD = 1000000007;

int d, position, a[N];
long long n;

struct Matrix {
    long long f[D][D];

    Matrix() {
        for (int i = 0; i <= d; i++) {
            for (int j = 0; j <= d; j++) {
                f[i][j] = 0;
            }
        }
    }

    Matrix multiply(const Matrix& other) const {
        Matrix result;
        for (int i = 0; i <= d; i++) {
            for (int j = 0; j <= d; j++) {
                for (int k = 0; k <= d; k++) {
                    result.f[i][j] = (result.f[i][j] + f[i][k] * other.f[k][j]) % MOD;
                }
            }
        }
        return result;
    }
} matrices[N];

Matrix rotate(int u) {
    u = (u + d) % d;
    Matrix m;
    for (int i = 0; i < d; i++) {
        m.f[i][(i + u) % d] = 1;
    }
    m.f[d][d] = 1;
    return m;
}

void setup() {
    for (int i = 1; i < d; i++) {
        matrices[0].f[i][i] = 1;
    }
    matrices[0].f[d][0] = 1;
    matrices[0].f[d][d] = 2;
    matrices[0].f[0][d] = -1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> d;
    for (position = 0; n > 0; position++, n /= d) {
        a[position] = n % d;
    }
    setup();
    for (int i = 1; i < position; i++) {
        matrices[i] = rotate(0);
        for (int j = 0; j < d; j++) {
            matrices[i] = matrices[i].multiply(matrices[i - 1]).multiply(rotate(1));
        }
    }
    Matrix ans = rotate(0);
    for (int i = position - 1; i >= 0; i--) {
        for (int j = 0; j < a[i]; j++) {
            ans = ans.multiply(matrices[i]).multiply(rotate(1));
        }
    }
    cout << (ans.f[d][d] + MOD) % MOD;
}
